using Modelos.Negocio;
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Configuration;
using System.Data;
using System.Data.SqlClient;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows.Forms;

namespace TerminalPedidos
{
    public partial class frmFotoProducto : AntdUI.Window
    {
        private string _producto;

        public frmFotoProducto(string producto  )
        {
            InitializeComponent();
            _producto = producto;
        }

        private void frmFotoProducto_Load(object sender, EventArgs e)
        {
            string hexString = obtenerImagen(_producto);

            // Convertir la cadena hexadecimal en un arreglo de bytes
            byte[] bytes = ConvertHexStringToByteArray(hexString);

            // Crear un MemoryStream desde los bytes
            using (MemoryStream ms = new MemoryStream(bytes))
            {
                // Crear imagen desde el stream
                Image imagen = Image.FromStream(ms);
                avatar1.Image = imagen;
            }
        }

        private void button5_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private string obtenerImagen(string codigo)
        {
            var configuracion = Modelos.Negocio.ConfigurationDBContext.obtener();

            SqlConnection con = new SqlConnection();
            con.ConnectionString = ConfigurationManager.ConnectionStrings["bd"].ConnectionString.Replace("PuntoVentaComercial", configuracion.empresa.Split('\\').Last());
            con.Open();

            SqlCommand comando = new SqlCommand("select admProductosFotos.CFOTOPRODUCTO from admProductos inner join admProductosFotos on admProductos.CIDFOTOPRODUCTO=admProductosFotos.CIDFOTOPRODUCTO where admProductos.CCODIGOPRODUCTO='" + codigo + "'", con);
            SqlDataReader lector = comando.ExecuteReader();

            if (lector.Read())
            {

                if (lector["CFOTOPRODUCTO"] == DBNull.Value)
                {
                    return "";
                }
                else
                {
                    return lector.GetString(0);
                }

            }
            else
            {
                return "";
            }
        }

        private byte[] ConvertHexStringToByteArray(string hex)
        {
            int length = hex.Length;
            byte[] bytes = new byte[length / 2];

            for (int i = 0; i < length; i += 2)
            {
                bytes[i / 2] = Convert.ToByte(hex.Substring(i, 2), 16);
            }

            return bytes;
        }
    }
}
